type Task = { id: string; title: string };
export function Titles({ tasks }: { tasks: Task[] }) {
  return tasks.length === 0 ? <p>No tasks yet.</p> : (
    <ul>{tasks.map(task => <li key={task.id}>{task.title}</li>)}</ul>
  );
}

import { useState } from "react";
export function Counter() {
  const [count, setCount] = useState(0);
  return <button type="button" onClick={() => { setCount(c => c + 1); setCount(c => c + 1); }}>{count}</button>;
}

import { useState } from "react";
export function TitleForm() {
  const [title, setTitle] = useState("");
  const [message, setMessage] = useState("");
  return <form onSubmit={e => { e.preventDefault(); setMessage(title.trim() ? "Ready" : "Enter a title"); }}>
    <label htmlFor="title">Task title</label>
    <input id="title" value={title} onChange={e => setTitle(e.currentTarget.value)} />
    <button type="submit">Check</button><p role="status">{message}</p>
  </form>;
}

