import { useEffect } from "react";
export function PageTitle({ count }: { count: number }) {
  useEffect(() => {
    const previous = document.title;
    document.title = `${count} tasks`;
    return () => { document.title = previous; };
  }, [count]);
  return null;
}

// A typed request helper; call it from a handler or a managed effect.
export async function readIdeas(signal?: AbortSignal): Promise<string[]> {
  const response = await fetch("./sample.json", { signal });
  if (!response.ok) throw new Error("Request failed");
  const data: unknown = await response.json();
  if (!Array.isArray(data) || !data.every(item => typeof item === "string")) throw new Error("Invalid ideas");
  return data;
}

